//! 🗜️ Explicit RFC1950 header, bounded raw codec and hexadecimal carrier under one native owner.
use super::{DeflateSnapshot,DeflateLevelHint};
use crate::store;
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding};
use semio_framework_value::{NativeDecodeControl,NativeEncodeControl,ValueError,ValueRefusalKind,native_decoding::NativeDecodeProgress,native_encoding::NativeEncodeProgress};
use semio_framework_deflate::{Inflater,InflateOutcome,RetainedInflateCloseStep,DeflateEncodeControl,DeflateEncodeProgress};
fn physical_error(error:semio_framework_deflate::DeflateError,prefix:&str)->ValueError{let kind=match error{semio_framework_deflate::DeflateError::OutputLimitExceeded=>ValueRefusalKind::OwnershipLimit,semio_framework_deflate::DeflateError::BadBlockType|semio_framework_deflate::DeflateError::BadStoredLength|semio_framework_deflate::DeflateError::BadHuffmanCode|semio_framework_deflate::DeflateError::BadDistance|semio_framework_deflate::DeflateError::UnexpectedEnd=>ValueRefusalKind::InvalidValue};ValueError::new(kind,format!("{prefix}: {error:?}"))}
fn envelope_error(error:store::semio_format::SemioError)->ValueError{match error{store::semio_format::SemioError::DecodingControl(error)=>error,store::semio_format::SemioError::InvalidPreamble(detail)=>ValueError::new(ValueRefusalKind::InvalidValue,format!("invalid semio preamble: {detail}")),store::semio_format::SemioError::InvalidBinaryHeader(detail)=>ValueError::new(ValueRefusalKind::InvalidValue,format!("invalid binary semio header: {detail}")),store::semio_format::SemioError::UnknownEnvelope(detail)=>ValueError::new(ValueRefusalKind::UnsupportedOwner,format!("unknown semio envelope: {detail}")),store::semio_format::SemioError::AmbiguousEnvelope=>ValueError::new(ValueRefusalKind::InvalidValue,"ambiguous semio envelope match")}}
struct History(Inflater);
impl Drop for History{fn drop(&mut self){let mut stalled=0;loop{let maximum=self.0.retained_allocated_bytes();match self.0.close_retained_step(256,maximum){RetainedInflateCloseStep::Complete=>break,RetainedInflateCloseStep::Pending{released_items,released_bytes}=>{if released_items==0&&released_bytes==0{stalled+=1;assert!(stalled<256,"Deflate history retirement made no progress");}else{stalled=0;}}}}assert!(self.0.retained_terminal_is_empty());}}
fn digit(ch:char)->Result<u8,ValueError>{ch.to_digit(16).and_then(|value|u8::try_from(value).ok()).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue, "invalid Deflate hexadecimal digit"))}
fn hex(text:&str,control:&mut NativeDecodeControl<'_>)->Result<Vec<u8>,ValueError>{
 control.begin_stage(text.len())?;let mut count=0usize;
 for ch in text.chars(){if !ch.is_whitespace(){digit(ch)?;count=count.checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit, "Deflate hexadecimal length overflow"))?;}control.advance(ch.len_utf8())?;}
 if count%2!=0{return Err(ValueError::new(ValueRefusalKind::InvalidValue, "odd Deflate hexadecimal length"))}let mut output=control.allocate_vec(count/2)?;let mut high=None;control.begin_stage(text.len())?;
 for ch in text.chars(){if !ch.is_whitespace(){let byte=digit(ch)?;if let Some(first)=high.take(){output.push(first*16+byte);}else{high=Some(byte);}}control.advance(ch.len_utf8())?;}Ok(output)
}
fn inflate_pass(history:&mut History,raw:&[u8],mut output:Option<&mut Vec<u8>>,maximum_output:usize,control:&mut NativeDecodeControl<'_>)->Result<(usize,u32),ValueError>{
 let known=output.as_ref().map(|value|value.capacity());control.begin_stage(known.unwrap_or(0))?;let mut operations=0usize;let mut offset=0usize;let mut pending=None;let mut count=0usize;let mut a=1u32;let mut b=0u32;
 loop{if pending.is_none()&&offset<raw.len(){pending=Some(raw[offset]);offset+=1;}
  match history.0.advance(&mut pending,offset==raw.len()).map_err(|error|physical_error(error,"Deflate physical refusal"))?{
   InflateOutcome::NeedInput=>{if pending.is_none()&&offset==raw.len(){return Err(ValueError::new(ValueRefusalKind::InvalidValue, "truncated Deflate payload"))}},
   InflateOutcome::Wrote(byte)=>{count=count.checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit, "Deflate payload length overflow"))?;if count>maximum_output{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit, "Deflate expansion exceeds caller output limit"))}if let Some(out)=output.as_deref_mut(){if out.len()==out.capacity(){return Err(ValueError::new(ValueRefusalKind::InvariantViolated, "Deflate materialization exceeded measured output"))}out.push(byte);}a=(a+u32::from(byte))%65521;b=(b+a)%65521;if known.is_some(){control.step()?;}},
   InflateOutcome::Done=>{let unused=history.0.terminal_unused_bytes().ok_or_else(||ValueError::new(ValueRefusalKind::InvariantViolated, "Deflate missing terminal state"))?;if pending.is_some()||offset.checked_sub(unused)!=Some(raw.len()){return Err(ValueError::new(ValueRefusalKind::InvalidValue, "trailing bytes after Deflate terminal block"))}control.checkpoint()?;return Ok((count,(b<<16)|a));}
  }operations=operations.checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit, "Deflate operation overflow"))?;if known.is_none(){control.step()?;}else if operations%256==0{control.checkpoint()?;}
 }
}
pub(super) fn decode(payload:&store::io_schema::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<DeflateSnapshot,ValueError>{
 let limits=control.limits();let length=match payload{store::io_schema::IoPayload::Binary(bytes)=>bytes.len(),store::io_schema::IoPayload::Text(text)=>text.len()};if length>limits.max_file_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit, "Deflate native input exceeds file limit"))}
 let mut callback_error=None;let mut progress=|event:NativeDecodeProgress|match control.checkpoint(SqliteSnapshotPhase::DecodeNative,event.completed,event.total){Ok(())=>true,Err(error)=>{callback_error=Some(error);false}};let mut native=NativeDecodeControl::new(limits.max_value_bytes,&mut progress);let result=(||->Result<_,ValueError>{let owned;
 let bytes=match payload{
  store::io_schema::IoPayload::Binary(bytes)=>store::semio_format::unwrap_binary_controlled(bytes,"stdio.deflate",store::semio_format::Component::Pack,1,&mut native).map_err(envelope_error)?,
  store::io_schema::IoPayload::Text(text)=>{let body=if text.starts_with("semio "){store::semio_format::split_text_preamble_controlled(text,"stdio.deflate",store::semio_format::Component::Dsl,1,&mut native).map_err(envelope_error)?}else{text.as_str()};owned=hex(body,&mut native)?;owned.as_slice()}
 };
 if bytes.len()<6{return Err(ValueError::new(ValueRefusalKind::InvalidValue, "zlib stream too short"))}let cmf=bytes[0];let flg=bytes[1];if cmf&15!=8{return Err(ValueError::new(ValueRefusalKind::UnsupportedOwner, "unsupported zlib compression method"))}if cmf>>4>7{return Err(ValueError::new(ValueRefusalKind::UnsupportedOwner, "unsupported zlib window indicator"))}if !(u16::from(cmf)*256+u16::from(flg)).is_multiple_of(31){return Err(ValueError::new(ValueRefusalKind::InvalidValue, "zlib CMF/FLG check failed"))}
 if flg&32!=0{return Err(ValueError::new(ValueRefusalKind::UnsupportedOwner, "Deflate native dictionary requires an owned dictionary authority"))}let start=2;let dict_id=None;let end=bytes.len()-4;let expected=u32::from_be_bytes(bytes[end..].try_into().map_err(|_|ValueError::new(ValueRefusalKind::InvariantViolated, "Deflate checksum width"))?);
 let window=1usize<<((cmf>>4)+8);native.charge(window)?;let mut history=History(Inflater::try_new_retained(window,window).map_err(|error|ValueError::new(ValueRefusalKind::OwnershipLimit,format!("Deflate history refusal: {error:?}")))?);history.0.reserve_retained_history(window).map_err(|error|ValueError::new(error.kind,error.reason))?;
 let (count,checksum)=inflate_pass(&mut history,&bytes[start..end],None,limits.max_rows.saturating_sub(1),&mut native)?;if checksum!=expected{return Err(ValueError::new(ValueRefusalKind::InvalidValue, "adler32 mismatch"))}let mut output=native.allocate_vec(count)?;history.0.reset_retained().map_err(|error|ValueError::new(ValueRefusalKind::InvariantViolated,format!("Deflate reset refusal: {error:?}")))?;let (materialized,checksum)=inflate_pass(&mut history,&bytes[start..end],Some(&mut output),limits.max_rows.saturating_sub(1),&mut native)?;if materialized!=count||checksum!=expected{return Err(ValueError::new(ValueRefusalKind::InvariantViolated, "Deflate materialization disagrees with measured stream"))}
 Ok(DeflateSnapshot{schema:native.copy_text(crate::STDIO_DEFLATE_DOCUMENT_SCHEMA)?,compression_method:cmf&15,window_bits:cmf>>4,compression_level_hint:DeflateLevelHint::from_bits(flg>>6),dict_id,payload:output})
})();drop(native);drop(progress);match callback_error{Some(error)=>Err(error),None=>result}
}
struct Encoder<'control,'callback>{control:&'control mut NativeEncodeControl<'callback>,stage:Option<semio_framework_deflate::DeflateEncodePhase>,completed:usize,overhead:usize,maximum_file_bytes:usize}
impl DeflateEncodeControl for Encoder<'_,'_>{
 fn admit(&mut self,bytes:usize)->Result<(),ValueError>{self.control.charge(bytes)}
 fn checkpoint(&mut self,event:DeflateEncodeProgress)->Result<(),ValueError>{if self.stage!=Some(event.phase){self.control.begin_stage(event.total)?;self.stage=Some(event.phase);self.completed=0;}if matches!(event.phase,semio_framework_deflate::DeflateEncodePhase::WriteOutput|semio_framework_deflate::DeflateEncodePhase::Finish)&&event.completed.checked_add(self.overhead).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit, "Deflate file size overflow"))?>self.maximum_file_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit, "Deflate native output exceeds file limit"))}let delta=event.completed.checked_sub(self.completed).ok_or_else(||ValueError::new(ValueRefusalKind::InvariantViolated, "Deflate encoder work moved backwards"))?;self.control.advance(delta)?;self.completed=event.completed;Ok(())}
}
pub(super) fn encode(snapshot:&DeflateSnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::io_schema::IoPayload,ValueError>{
 let limits=control.limits();if snapshot.compression_method!=8||snapshot.window_bits!=7||snapshot.dict_id.is_some(){return Err(ValueError::new(ValueRefusalKind::UnsupportedOwner, "Deflate native producer requires dictionary-free 32-KiB RFC1950 authority"))}if snapshot.payload.len().checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit, "Deflate row overflow"))?>limits.max_rows{return Err(ValueError::new(ValueRefusalKind::WorkLimit, "Deflate native output exceeds row limit"))}
 let mut callback_error=None;let mut progress=|event:NativeEncodeProgress|match control.checkpoint(SqliteSnapshotPhase::EncodeNative,event.completed,event.total){Ok(())=>true,Err(error)=>{callback_error=Some(error);false}};let mut native=NativeEncodeControl::new(limits.max_value_bytes,&mut progress);let result=(||->Result<_,ValueError>{let header=if snapshot.dict_id.is_some(){6usize}else{2};let prefix=store::semio_format::declared_envelope_prefix_len("stdio.deflate",match encoding{SnapshotEncoding::Binary=>store::semio_format::Component::Pack,SnapshotEncoding::Text=>store::semio_format::Component::Dsl},1)?;let overhead=header.checked_add(4).and_then(|size|size.checked_add(prefix)).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit, "Deflate file size overflow"))?;
 let raw=semio_framework_deflate::deflate_controlled(&snapshot.payload,&mut Encoder{control:&mut native,stage:None,completed:0,overhead,maximum_file_bytes:limits.max_file_bytes})?;let zlib_length=header.checked_add(raw.len()).and_then(|size|size.checked_add(4)).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit, "Deflate file size overflow"))?;let body_length=if encoding==SnapshotEncoding::Text{zlib_length.checked_mul(2).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit, "Deflate hex size overflow"))?}else{zlib_length};if body_length.checked_add(prefix).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit, "Deflate file size overflow"))?>limits.max_file_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit, "Deflate native output exceeds file limit"))}
 let mut zlib=native.allocate_vec(zlib_length)?;let cmf=(snapshot.window_bits<<4)|snapshot.compression_method;let high=(snapshot.compression_level_hint.to_bits()<<6)|if snapshot.dict_id.is_some(){32}else{0};let check=(31-(u16::from(cmf)*256+u16::from(high))%31)%31;zlib.extend_from_slice(&[cmf,high|u8::try_from(check).map_err(|error|ValueError::new(ValueRefusalKind::InvariantViolated,error.to_string()))?]);if let Some(id)=snapshot.dict_id{zlib.extend_from_slice(&id.to_be_bytes());}
 native.begin_stage(raw.len())?;for chunk in raw.chunks(256){zlib.extend_from_slice(chunk);native.advance(chunk.len())?;}
 let mut a=1u32;let mut b=0u32;native.begin_stage(snapshot.payload.len())?;for chunk in snapshot.payload.chunks(256){for byte in chunk{a=(a+u32::from(*byte))%65521;b=(b+a)%65521;}native.advance(chunk.len())?;}zlib.extend_from_slice(&((b<<16)|a).to_be_bytes());
 match encoding{SnapshotEncoding::Binary=>Ok(store::io_schema::IoPayload::Binary(store::semio_format::wrap_binary_controlled("stdio.deflate",store::semio_format::Component::Pack,1,&zlib,&mut native)?)),SnapshotEncoding::Text=>{let mut bytes=native.allocate_vec(body_length)?;native.begin_stage(zlib.len())?;const HEX:&[u8;16]=b"0123456789abcdef";for chunk in zlib.chunks(256){for byte in chunk{bytes.push(HEX[usize::from(byte>>4)]);bytes.push(HEX[usize::from(byte&15)]);}native.advance(chunk.len())?;}let text=String::from_utf8(bytes).map_err(|error|ValueError::new(ValueRefusalKind::InvariantViolated,error.to_string()))?;Ok(store::io_schema::IoPayload::Text(store::semio_format::wrap_text_controlled("stdio.deflate",store::semio_format::Component::Dsl,1,&text,&mut native)?))}}
})();drop(native);drop(progress);match callback_error{Some(error)=>Err(error),None=>result}
}

/// 🫧️ Bare RFC1950 expansion preserves one caller-owned control across both physical passes.
pub fn decompress_zlib(bytes:&[u8],maximum_output:usize,control:&mut NativeDecodeControl<'_>)->Result<Vec<u8>,ValueError> {
 if bytes.len()<6{return Err(ValueError::new(ValueRefusalKind::InvalidValue, "zlib stream too short"))}let cmf=bytes[0];let flg=bytes[1];if cmf&15!=8||cmf>>4>7{return Err(ValueError::new(ValueRefusalKind::UnsupportedOwner, "unsupported zlib method or window"))}if !(u16::from(cmf)*256+u16::from(flg)).is_multiple_of(31){return Err(ValueError::new(ValueRefusalKind::InvalidValue, "zlib CMF/FLG check failed"))}if flg&32!=0{return Err(ValueError::new(ValueRefusalKind::UnsupportedOwner, "bare zlib consumer has no preset dictionary authority"))}
 let end=bytes.len()-4;let expected=u32::from_be_bytes(bytes[end..].try_into().map_err(|_|ValueError::new(ValueRefusalKind::InvariantViolated, "zlib checksum width"))?);let window=1usize<<((cmf>>4)+8);control.charge(window)?;let mut history=History(Inflater::try_new_retained(window,window).map_err(|error|ValueError::new(ValueRefusalKind::OwnershipLimit,format!("zlib history refusal: {error:?}")))?);history.0.reserve_retained_history(window).map_err(|error|ValueError::new(error.kind,error.reason))?;
 let (count,checksum)=inflate_pass(&mut history,&bytes[2..end],None,maximum_output,control)?;if checksum!=expected{return Err(ValueError::new(ValueRefusalKind::InvalidValue, "zlib adler32 mismatch"))}let mut output=control.allocate_vec(count)?;history.0.reset_retained().map_err(|error|ValueError::new(ValueRefusalKind::InvariantViolated,format!("zlib reset refusal: {error:?}")))?;let (materialized,checksum)=inflate_pass(&mut history,&bytes[2..end],Some(&mut output),maximum_output,control)?;if materialized!=count||checksum!=expected{return Err(ValueError::new(ValueRefusalKind::InvariantViolated, "zlib measured and materialized streams disagree"))}Ok(output)
}
/// 🗜️ Bare RFC1950 emission admits code tables, compressed bytes and framing cumulatively.
pub fn compress_zlib(bytes:&[u8],maximum_file:usize,control:&mut NativeEncodeControl<'_>)->Result<Vec<u8>,ValueError> {
 let raw=semio_framework_deflate::deflate_controlled(bytes,&mut Encoder{control,stage:None,completed:0,overhead:6,maximum_file_bytes:maximum_file})?;let size=raw.len().checked_add(6).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit, "zlib output size overflow"))?;if size>maximum_file{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit, "zlib output exceeds caller file limit"))}let mut output=control.allocate_vec(size)?;output.extend_from_slice(&[0x78,0x01]);control.begin_stage(raw.len())?;for chunk in raw.chunks(256){output.extend_from_slice(chunk);control.advance(chunk.len())?;}
 let mut a=1u32;let mut b=0u32;control.begin_stage(bytes.len())?;for chunk in bytes.chunks(256){for byte in chunk{a=(a+u32::from(*byte))%65521;b=(b+a)%65521;}control.advance(chunk.len())?;}output.extend_from_slice(&((b<<16)|a).to_be_bytes());Ok(output)
}
